"""Fixed master, origin and thickness; separately declared grid evaluation."""
from regularized_surface import *

def evaluate(master_path,measurement_path,out,pitch):
 out=Path(out);out.mkdir(parents=True,exist_ok=False);m,c=verify_measurement(measurement_path);master=gzread(master_path);assert master['grid_origin']==[0,0,0];cc=compile_master(master,{'pitch':pitch},max_candidate_cells=350000,max_output_cells=20000);rr=make_render_data(cc);gzwrite(out/'compiled.cells.json.gz',cc);gzwrite(out/'region.render.json.gz',rr);re=compile_master(master,{'pitch':pitch},max_candidate_cells=350000,max_output_cells=20000);mm,mc=verify_measurement(ROOT/'generated/mutated_measurement/measurements.json.gz');mutmaster,mfit=fit_surface(mm,mc);mut=compile_master(mutmaster,{'pitch':pitch},max_candidate_cells=350000,max_output_cells=20000);mutrender=make_render_data(mut);d={tuple(r[:3]) for r in cc['cells']}^{tuple(r[:3]) for r in mut['cells']};ys=[(p[1]+.5)*pitch for p in d];metrics,_=projections(rr,m,c);proj={}
 for name,v in m['views'].items():
  pm=project(rr,v,c['alignment']['character_height_m_for_test']);qm=project(mutrender,v,c['alignment']['character_height_m_for_test']);py=np.where((pm^qm).any(1))[0];s=c['alignment']['character_height_m_for_test']/v['scale_px_per_unit'];allowed=[math.floor(v['sole_y']-(max(ys)+pitch/2)/s),math.ceil(v['sole_y']-(min(ys)-pitch/2)/s)];proj[name]={'changed_pixels':int((pm^qm).sum()),'changed_y_range':[int(py.min()),int(py.max())] if len(py) else None,'allowed_y_range_from_cell_faces':allowed,'locality_pass':bool(len(py) and py.min()>=allowed[0] and py.max()<=allowed[1])}
 report={'source_sha256':m['source_sha256'],'measurement_sha256':sha(measurement_path),'frozen_master_sha256':sha(master_path),'frozen_continuous_operations_sha256':digest(master['components']),'normal_thickness_m':.025,'grid_origin':[0,0,0],'pitch_m':pitch,'request_status':'parent explicitly permits 12.5mm for this thin ROI only; no whole-character resolution change','cells':len(cc['cells']),'quads':rr['quad_count'],'candidate_cells':cc['candidate_cells'],'compiler_sha256':cc['compiler_source_hash'],'same_input_common_recompile_exact':re==cc,'same_input_mesh_exact':make_render_data(re)==rr,'structure':components(cc['cells']),'projection':metrics,'local_pixel_regression':{'changed_source_pixels':1738,'changed_source_rows':[548,559],'changed_occupancy_cells':len(d),'cell_center_y_m':[min(ys),max(ys)],'projection':proj},'art_approved':False,'depth_and_back_correspondence_resolved':False};write(out/'verification.json',report)
 lo=np.array(rr['bounds']['min']);hi=np.array(rr['bounds']['max']);center=(lo+hi)/2;span=float(max(hi-lo)*1.4);sheet=Image.new('RGB',(1536,850),'white');dr=ImageDraw.Draw(sheet);dr.text((12,10),'Same continuous master and 25mm normal thickness | fixed origin [0,0,0] | thin ROI 12.5mm grid',fill='black')
 for i,(name,yaw,tilt) in enumerate([('front',0,0),('three_quarter',45,15),('side',90,0),('back',180,0)]):
  im=raster(rr,math.radians(yaw),math.radians(tilt),center,span,size=384);d0=ImageDraw.Draw(im);d0.text((8,8),name+' / actual 12.5mm common mesh CPU',fill='black');im.save(out/f'cpu_{name}.png');sheet.paste(im,(i*384,35));old=Image.open(SURFACE/'generated'/f'cpu_{name}.png');sheet.paste(old,(i*384,430))
 dr.text((12,820),'Top: 12.5mm evaluation. Bottom: preserved 25mm failure. No thickness increase, island deletion or fill; likeness remains unresolved.',fill='black');sheet.save(out/'fixed_master_grid_comparison.jpg',quality=89);write(out/'render_provenance.json',{'renderer_sha256':sha(CPU_SOURCE),'mesh_sha256':sha(out/'region.render.json.gz'),'comparison_sha256':sha(out/'fixed_master_grid_comparison.jpg'),'camera_center':center.tolist(),'span_m':span,'GPU_screenshot':False});print(json.dumps(report));budget()
if __name__=='__main__':evaluate(SURFACE/'generated/master.json.gz',ROOT/'generated/measured/measurements.json.gz',SURFACE/'evaluation125',.0125)
